/* ============================================================
   data.js — AIF-C01 のコンテンツ

   engine.js が参照するグローバルを同名で定義する（データ契約）。
   詳細は ../CLAUDE.md 10-3節・14-2節を参照。

   ★現在は各形式が動作することを確認するための第1チャンク。
     目標量（CLAUDE.md 第15節）に向けて50問ずつ追加していく。
       単語帳 152枚 ／ 過去問4択 70問 ／ 複数選択 40問 ／
       シナリオ 150問 ／ 順序・マッチング ／ チートシート7本

   ※収録済みの内容はすべて独自作成（外部サイトからの転載は無し）。
   ============================================================ */

// ─── 単語帳カテゴリ（CLAUDE.md 第15節の設計） ───────────────
// 過去問カテゴリ（QCAT）のIDは、ここのIDから 'cat_' を除いたものにすること。
// engine.js の weakDiagnosis() がこの規約で両者を突き合わせる。
const FC_CATS_DEF = [
  {id:'cat_ai_basic',    name:'AI・MLの基礎'},
  {id:'cat_ml_flow',     name:'MLライフサイクルと評価'},
  {id:'cat_genai',       name:'生成AIの基礎'},
  {id:'cat_prompt',      name:'プロンプトエンジニアリング'},
  {id:'cat_bedrock',     name:'Amazon Bedrock'},
  {id:'cat_sagemaker',   name:'Amazon SageMaker'},
  {id:'cat_aiservices',  name:'AIサービス群'},
  {id:'cat_responsible', name:'責任あるAI'},
  {id:'cat_secgov',      name:'セキュリティ・ガバナンス'},
];

// ─── 単語帳カード ──────────────────────────────────────────
// キーは FC_CATS_DEF の表示名と一致させること。IDは B0001 から通し番号。
const SAMPLE = {
  'AI・MLの基礎': [
    {id:'B0001', term:'人工知能（AI）', def:'人間の知的なふるまい（認識・推論・判断・言語理解など）をコンピューターで実現する技術の総称。機械学習はAIを実現する手法のひとつで、AIのほうが広い概念。'},
    {id:'B0002', term:'機械学習（ML）', def:'ルールを人が書く代わりに、データからパターンを学習させて予測や判断を行わせる手法。AIの一分野。'},
    {id:'B0003', term:'ディープラーニング（深層学習）', def:'多層のニューラルネットワークを使う機械学習の手法。画像認識や自然言語処理で高い性能を出し、生成AIの基盤にもなっている。機械学習の一分野。'},
    {id:'B0004', term:'教師あり学習（Supervised Learning）', def:'正解ラベルが付いたデータで学習させる方式。入力と正解の対応を学び、未知の入力に対する予測を行う。分類（スパム判定など）と回帰（価格予測など）が代表例。'},
    {id:'B0005', term:'教師なし学習（Unsupervised Learning）', def:'正解ラベルのないデータから、データ自身の構造やパターンを見つける方式。クラスタリング（顧客のグループ分け）や次元削減が代表例。'},
    {id:'B0006', term:'強化学習（Reinforcement Learning）', def:'エージェントが環境の中で行動し、報酬を最大化するように試行錯誤で学習する方式。ゲームAIやロボット制御、推薦の最適化などに使われる。'},
    {id:'B0007', term:'自己教師あり学習（Self-Supervised Learning）', def:'ラベルなしデータから、データ自身の一部を隠して当てさせるなどして学習信号を作り出す方式。基盤モデルの事前学習で広く使われる。'},
    {id:'B0008', term:'分類（Classification）', def:'入力がどのカテゴリに属するかを予測するタスク。「スパムか否か」の二値分類と、「犬・猫・鳥」のような多クラス分類がある。教師あり学習の代表例。'},
    {id:'B0009', term:'回帰（Regression）', def:'連続する数値を予測するタスク。売上金額や気温、住宅価格の予測など。分類と並ぶ教師あり学習の代表例。'},
    {id:'B0010', term:'クラスタリング', def:'似たデータ同士を自動的にグループへまとめる教師なし学習の手法。顧客セグメンテーションや異常検知の下地に使われる。正解ラベルは不要。'},
    {id:'B0011', term:'特徴量（Feature）', def:'モデルへの入力として使う、データの各項目のこと。住宅価格の予測なら「面積」「築年数」「駅からの距離」など。何を特徴量にするかが精度を大きく左右する。'},
    {id:'B0012', term:'ラベル（正解データ）', def:'教師あり学習で、各データに付ける「正解」のこと。モデルはこのラベルと自分の予測との差を小さくするように学習する。'},
    {id:'B0013', term:'過学習（オーバーフィッティング）', def:'訓練データに適合しすぎて、未知のデータに対する性能が落ちる状態。訓練データの精度は高いのに検証データの精度が低い場合に疑う。データ追加・正則化・早期終了などで対処する。'},
    {id:'B0014', term:'過少適合（アンダーフィッティング）', def:'モデルが単純すぎるなどの理由で、訓練データのパターンすら捉えきれていない状態。訓練データでも検証データでも精度が低い。過学習とは逆の症状。'},
    {id:'B0015', term:'推論（Inference）', def:'学習済みモデルに新しい入力を与えて予測結果を得ること。学習（トレーニング）とは区別される。実運用でコストが継続的にかかるのは主にこちら。'},
    {id:'B0016', term:'ニューラルネットワーク', def:'人間の神経細胞のつながりを模した計算モデル。入力層・隠れ層・出力層からなり、層を深く重ねたものがディープラーニング。'},
    {id:'B0017', term:'転移学習（Transfer Learning）', def:'あるタスクで学習済みのモデルを、別の関連タスクに再利用する手法。ゼロから学習するより少ないデータと時間で済む。基盤モデルの活用もこの考え方に近い。'},
    {id:'B0018', term:'学習データのバイアス', def:'学習データの偏りが、モデルの予測の偏りとして現れること。特定の属性のデータが少ないと、そのグループに対する精度が低くなる。責任あるAIの中心的な論点。'},
  ],
  'MLライフサイクルと評価': [
    {id:'B0019', term:'MLライフサイクル', def:'ビジネス課題の定義 → データの収集と準備 → モデルの学習 → 評価 → デプロイ → 監視、という一連の流れ。デプロイして終わりではなく、監視と再学習が続く循環になる。'},
    {id:'B0020', term:'データ前処理', def:'欠損値の補完、外れ値の除去、表記ゆれの統一、正規化など、学習に使える形にデータを整える工程。ML作業時間の多くを占める。'},
    {id:'B0021', term:'特徴量エンジニアリング', def:'生のデータから、モデルが学習しやすい特徴量を設計・加工すること。日付から「曜日」を作るなど。精度への影響が大きい。'},
    {id:'B0022', term:'訓練データ／検証データ／テストデータ', def:'訓練データで学習し、検証データでハイパーパラメータを調整し、テストデータで最終的な性能を測る。テストデータを調整に使うと性能を過大評価してしまう。'},
    {id:'B0023', term:'ハイパーパラメータ', def:'学習率やバッチサイズなど、学習を始める前に人が決める設定値。モデルが学習で獲得するパラメータ（重み）とは区別される。'},
    {id:'B0024', term:'混同行列（Confusion Matrix）', def:'分類モデルの予測と実際の正解を、真陽性・偽陽性・真陰性・偽陰性の4区分で集計した表。適合率や再現率はここから計算される。'},
    {id:'B0025', term:'適合率（Precision）', def:'モデルが「陽性」と判定したもののうち、実際に陽性だった割合。誤検知（False Positive）を減らしたい場面で重視する。'},
    {id:'B0026', term:'再現率（Recall）', def:'実際に陽性であるもののうち、モデルが正しく「陽性」と判定できた割合。見逃し（False Negative）を減らしたい場面（病気の検出など）で重視する。'},
    {id:'B0027', term:'F1スコア', def:'適合率と再現率の調和平均。どちらか一方に偏らず両立させたいときの総合指標として使う。'},
    {id:'B0028', term:'正解率（Accuracy）', def:'全体のうち正しく予測できた割合。分かりやすい反面、陽性が極端に少ないデータでは「全部陰性」と答えるだけで高くなってしまうため、単独では判断できない。'},
    {id:'B0029', term:'AUC-ROC', def:'分類モデルが陽性と陰性をどれだけ区別できているかを、判定のしきい値によらず0〜1で表す指標。1に近いほど良い。'},
    {id:'B0030', term:'MSE / RMSE（平均二乗誤差）', def:'回帰モデルの評価指標。予測値と実際の値の差を二乗して平均したもの（RMSEはその平方根）。小さいほど良い。'},
    {id:'B0031', term:'モデルドリフト', def:'時間の経過とともに実世界のデータ分布が変化し、モデルの精度が劣化していく現象。継続的な監視と再学習が必要になる。'},
    {id:'B0032', term:'交差検証（Cross Validation）', def:'データを複数に分割し、訓練と検証の組み合わせを変えながら繰り返し評価する手法。データが少ないときでも性能を安定して見積もれる。'},
    {id:'B0033', term:'MLOps', def:'機械学習モデルの開発から本番運用・監視・再学習までを、自動化された繰り返し可能な仕組みとして回す考え方。DevOpsの機械学習版。'},
    {id:'B0034', term:'バッチ推論とリアルタイム推論', def:'バッチ推論はまとまったデータを定期的にまとめて処理する方式でコストが安い。リアルタイム推論は都度応答する方式で低遅延だが常時稼働のコストがかかる。要件で選ぶ。'},
  ],
  '生成AIの基礎': [
    {id:'B0035', term:'生成AI（Generative AI）', def:'テキスト・画像・音声・コードなど、新しいコンテンツを作り出すAI。分類や予測を行う従来のMLと違い、出力そのものを生成する点が特徴。'},
    {id:'B0036', term:'基盤モデル（Foundation Model / FM）', def:'大量かつ多様なデータで事前学習された大規模モデル。そのまま、あるいは少しの適応で多様なタスクに転用できる。生成AIの土台となる。'},
    {id:'B0037', term:'大規模言語モデル（LLM）', def:'膨大なテキストで学習し、文章の生成・要約・翻訳・質問応答などを行う基盤モデル。テキストを扱う基盤モデルの代表格。'},
    {id:'B0038', term:'トークン', def:'モデルがテキストを扱う際の最小単位。単語より細かい単位に分割されることが多い。入力・出力のトークン数が課金やコンテキスト長の基準になる。'},
    {id:'B0039', term:'トークン化（Tokenization）', def:'文章をトークンの列に分割する処理。日本語と英語では同じ文字数でもトークン数が変わるため、コスト見積もりに影響する。'},
    {id:'B0040', term:'埋め込み（Embedding）', def:'テキストや画像を、意味的な近さが距離として表現される数値ベクトルに変換したもの。意味検索やRAGの検索部分で使われる。'},
    {id:'B0041', term:'ベクトルデータベース', def:'埋め込みベクトルを保存し、意味的に近いものを高速に検索できるデータストア。RAGの検索基盤として使われる。'},
    {id:'B0042', term:'コンテキストウィンドウ', def:'モデルが一度に扱えるトークン数の上限。プロンプトと出力の合計がこの範囲に収まる必要がある。長い文書を扱う際の制約になる。'},
    {id:'B0043', term:'ハルシネーション（幻覚）', def:'モデルが事実に基づかない内容を、もっともらしく生成してしまう現象。RAGで根拠情報を与える、出力を検証するなどの対策が要る。'},
    {id:'B0044', term:'温度（Temperature）', def:'出力のランダム性を調整するパラメータ。低くすると決定的で一貫した出力に、高くすると多様で創造的な出力になる。'},
    {id:'B0045', term:'Top-K', def:'次のトークンの候補を、確率が高い上位K個に絞る設定。Kを小さくすると出力が安定し、大きくすると多様になる。'},
    {id:'B0046', term:'Top-P（Nucleus Sampling）', def:'次のトークンの候補を、累積確率がPに達するまでの範囲に絞る設定。候補の個数ではなく確率の合計で絞る点がTop-Kと異なる。'},
    {id:'B0047', term:'最大トークン数（Max Tokens）', def:'1回の応答で生成するトークン数の上限を決める設定。長すぎる出力やコストの暴走を抑える役割がある。'},
    {id:'B0048', term:'トランスフォーマー（Transformer）', def:'文中のどの語に注目すべきかを重み付けする「アテンション」を用いたモデル構造。現在の大規模言語モデルの土台になっている。'},
    {id:'B0049', term:'事前学習（Pre-training）', def:'大量の一般的なデータで基盤モデルの土台を作る工程。膨大な計算資源を要するため、利用者は通常、既に事前学習済みのモデルを使う。'},
    {id:'B0050', term:'マルチモーダルモデル', def:'テキストだけでなく画像・音声など複数種類の入力や出力を扱えるモデル。「画像を見せて説明させる」といった使い方ができる。'},
    {id:'B0051', term:'拡散モデル（Diffusion Model）', def:'ノイズだらけの状態から少しずつノイズを取り除いて画像を作り出す生成手法。画像生成モデルで広く使われている。'},
    {id:'B0052', term:'RAG（検索拡張生成）', def:'質問に関連する文書を外部データから検索し、その内容を根拠としてプロンプトに含めて回答させる手法。モデルを再学習せずに最新情報や社内知識を反映できる。'},
  ],
  'プロンプトエンジニアリング': [
    {id:'B0053', term:'プロンプト', def:'基盤モデルに与える指示や入力のこと。指示・文脈・入力データ・出力形式の指定などを含む。同じモデルでもプロンプト次第で結果が大きく変わる。'},
    {id:'B0054', term:'プロンプトエンジニアリング', def:'狙った出力を得られるようにプロンプトを設計・改善する取り組み。モデルを再学習させないため、最も低コストな精度改善の手段。'},
    {id:'B0055', term:'ゼロショットプロンプティング', def:'例を一切与えず、指示だけでタスクを実行させる方法。基盤モデルが事前学習で得た知識だけに頼る。'},
    {id:'B0056', term:'ワンショットプロンプティング', def:'例を1つだけ示してからタスクを実行させる方法。ゼロショットとフューショットの中間にあたる。'},
    {id:'B0057', term:'フューショットプロンプティング', def:'いくつかの入出力例をプロンプトに含めて、期待する形式や傾向を示す方法。ゼロショットより精度が上がることが多い。'},
    {id:'B0058', term:'思考の連鎖（Chain-of-Thought）', def:'途中の推論ステップを順に書かせることで、複雑な問題の正答率を上げる手法。「順を追って考えてください」といった指示を与える。'},
    {id:'B0059', term:'システムプロンプト', def:'モデルの役割や守るべき制約を、会話全体にわたって指定する土台の指示。「あなたは丁寧な日本語のカスタマーサポートです」など。'},
    {id:'B0060', term:'役割の指定（ペルソナ）', def:'「専門家として」「初心者向けに」など立場や読み手を指定することで、文体や詳しさを制御する手法。'},
    {id:'B0061', term:'出力形式の指定', def:'JSON・箇条書き・表など、出力の形を明示的に指定すること。後続のプログラムで処理しやすくなり、ぶれも減る。'},
    {id:'B0062', term:'ネガティブプロンプト', def:'出力に含めたくない要素を明示する指定。画像生成で不要な要素を避けたい場合などに使う。'},
    {id:'B0063', term:'プロンプトテンプレート', def:'共通部分を固定し、可変部分だけを差し込む形にしたプロンプトの雛形。品質を安定させ、運用しやすくする。'},
    {id:'B0064', term:'プロンプトインジェクション', def:'悪意ある入力によって、モデルに本来の指示を無視させたり意図しない動作をさせたりする攻撃。入力の検証やGuardrailsによる防御が必要。'},
    {id:'B0065', term:'ジェイルブレイク', def:'モデルに設定された安全上の制限を、巧妙な言い回しで回避させようとする行為。Guardrailsなどの多層的な防御で対処する。'},
    {id:'B0066', term:'プロンプトリーキング', def:'システムプロンプトなど、開示するつもりのない指示内容をモデルに吐き出させる攻撃。機密をプロンプトに書かない設計が基本の対策。'},
  ],
  'Amazon Bedrock': [
    {id:'B0067', term:'Amazon Bedrock', def:'複数のプロバイダーの基盤モデルを、単一のAPIからサーバーレスで利用できるフルマネージドサービス。インフラの管理が不要。'},
    {id:'B0068', term:'Bedrock のモデルアクセス', def:'Bedrockで各基盤モデルを使う前に、アカウント側でそのモデルの利用を有効化する必要がある。使えるモデルはリージョンによっても異なる。'},
    {id:'B0069', term:'Amazon Titan', def:'AWS自身が提供する基盤モデルのファミリー。テキスト生成や埋め込みの生成などに対応する。'},
    {id:'B0070', term:'Bedrock Knowledge Bases', def:'自社データを検索対象として基盤モデルに与える、RAG（検索拡張生成）をマネージドで実現する機能。回答の根拠を自社データに置ける。'},
    {id:'B0071', term:'Bedrock Agents', def:'ユーザーの要求を複数のステップに分解し、APIの呼び出しなどを行ってタスクを実行させる機能。単なる文章生成にとどまらない処理ができる。'},
    {id:'B0072', term:'Bedrock Guardrails', def:'望ましくない話題や有害な内容、個人情報などを入出力の両方でフィルタする安全機構。責任あるAIの実装手段のひとつ。'},
    {id:'B0073', term:'Guardrailsのフィルタ種別', def:'有害コンテンツのフィルタ、拒否したいトピックの指定、禁止語句、個人情報（PII）のマスキングなどを組み合わせて設定できる。'},
    {id:'B0074', term:'Bedrock Model Evaluation', def:'複数の基盤モデルを、自動指標や人手の評価で比較できる機能。用途に対してどのモデルが適切かを選ぶために使う。'},
    {id:'B0075', term:'プロンプト管理（Prompt Management）', def:'プロンプトをバージョン付きで保存・共有・再利用できるBedrockの機能。品質のばらつきを抑え、改善の履歴を残せる。'},
    {id:'B0076', term:'オンデマンド課金（Bedrock）', def:'事前契約なしに、処理した入力・出力のトークン量に応じて支払う課金方式。利用量が読めない段階や試作に向く。'},
    {id:'B0077', term:'Provisioned Throughput', def:'一定のスループットを確保して予約する課金方式。安定した大量処理が必要な本番運用に向く。時間単位で確保するためコストは先に決まる。'},
    {id:'B0078', term:'バッチ推論（Bedrock）', def:'大量の入力をまとめて非同期で処理する方式。即時応答が不要な用途では、リアルタイム呼び出しより安く済む。'},
    {id:'B0079', term:'ファインチューニング', def:'ラベル付きの自社データで基盤モデルを追加学習し、特定タスクへの適合度を高める手法。RAGより準備コストは高いが、口調や形式の一貫性を出しやすい。'},
    {id:'B0080', term:'継続的事前学習（Continued Pre-training）', def:'ラベルなしの自社ドメインデータで基盤モデルの事前学習を継続し、専門領域の知識を底上げする手法。大量のデータが要る。'},
    {id:'B0081', term:'カスタムモデル（Bedrock）', def:'ファインチューニングや継続的事前学習で作った自分専用のモデル。利用にはProvisioned Throughputの確保が必要になる。'},
    {id:'B0082', term:'RAGとファインチューニングの使い分け', def:'最新情報や社内文書を根拠にしたいならRAG、口調や出力形式を一貫させたいならファインチューニング。情報が頻繁に変わるならRAGが有利。'},
    {id:'B0083', term:'BedrockとSageMakerの違い', def:'Bedrockは既製の基盤モデルをAPIで使うサービスで、インフラ管理が不要。SageMakerはモデルの構築・学習・デプロイまでを自分で行うための基盤。手軽さと自由度のトレードオフ。'},
    {id:'B0084', term:'Bedrockのデータの取り扱い', def:'Bedrockに送ったプロンプトや推論データが、基盤モデルの学習に使われることはない。データは暗号化され、他の顧客やモデル提供者と共有されない。'},
    {id:'B0085', term:'推論パラメータの調整', def:'温度・Top-K・Top-P・最大トークン数などを変えて、出力の安定性や多様性、コストを制御すること。再学習せずに挙動を変えられる。'},
    {id:'B0086', term:'埋め込みモデル（Embedding Model）', def:'テキストなどをベクトルに変換する専用のモデル。RAGでは、文書と質問の両方をこのモデルでベクトル化して近さを比べる。'},
  ],
  'Amazon SageMaker': [
    {id:'B0087', term:'Amazon SageMaker AI', def:'機械学習モデルの構築・学習・デプロイ・運用を一通り行えるフルマネージドの基盤。既製モデルを使うBedrockより自由度が高いぶん、扱う知識も必要になる。'},
    {id:'B0088', term:'SageMaker Studio', def:'データ準備からモデルの学習・デプロイまでをブラウザ上で行える統合開発環境。'},
    {id:'B0089', term:'SageMaker Canvas', def:'コードを書かずにGUI操作で機械学習モデルを作成・予測できるサービス。ビジネス分析担当者など、非エンジニアの利用を想定している。'},
    {id:'B0090', term:'SageMaker JumpStart', def:'あらかじめ用意された学習済みモデルやソリューションテンプレートを、数クリックで展開できる機能。ゼロから作らずに始められる。'},
    {id:'B0091', term:'SageMaker Autopilot', def:'データを渡すと、前処理・アルゴリズム選択・ハイパーパラメータ調整を自動で行い、モデルを作ってくれる自動機械学習（AutoML）の機能。'},
    {id:'B0092', term:'SageMaker Data Wrangler', def:'データの取り込み・可視化・変換をGUIで行える機能。前処理の工程を短縮できる。'},
    {id:'B0093', term:'SageMaker Feature Store', def:'作成した特徴量を保存・共有・再利用するための一元的な保管場所。学習時と推論時で特徴量の作り方がずれる問題を防げる。'},
    {id:'B0094', term:'SageMaker Ground Truth', def:'学習用データにラベルを付ける作業を支援するサービス。人手によるラベリングと自動ラベリングを組み合わせられる。'},
    {id:'B0095', term:'SageMaker Clarify', def:'データやモデルに含まれるバイアスを検出し、予測結果に対する各特徴量の寄与（説明可能性）を示す機能。公平性・説明可能性の実装手段。'},
    {id:'B0096', term:'SageMaker Model Monitor', def:'本番稼働中のモデルの入力データや予測結果の変化（ドリフト）を監視し、品質劣化を検知する機能。'},
    {id:'B0097', term:'SageMaker Model Cards', def:'モデルの用途・学習データ・評価結果・制限事項などを記録する文書化の機能。ガバナンスと透明性の確保に使う。'},
    {id:'B0098', term:'SageMaker Pipelines', def:'データ準備から学習・評価・デプロイまでの一連の工程を、繰り返し実行できるワークフローとして定義する機能。MLOpsの中核。'},
    {id:'B0099', term:'SageMaker Model Registry', def:'学習したモデルをバージョン管理し、承認状態を管理して本番へ進める仕組み。'},
    {id:'B0100', term:'SageMaker エンドポイント', def:'学習済みモデルをリアルタイム推論用に公開する仕組み。常時起動のため、呼び出しが無くても稼働時間に応じた費用がかかる。'},
    {id:'B0101', term:'SageMaker Serverless Inference', def:'リクエストが来たときだけ計算資源を割り当てる推論方式。呼び出しが断続的な用途ではコストを抑えられる。'},
    {id:'B0102', term:'SageMaker バッチ変換（Batch Transform）', def:'大量のデータをまとめて推論する方式。即時応答が不要な用途では、常時稼働のエンドポイントより安く済む。'},
    {id:'B0103', term:'マネージドスポットトレーニング', def:'余剰のコンピューティング資源を使って学習コストを大きく下げる仕組み。中断される可能性があるため、中断に耐えられる学習に向く。'},
    {id:'B0104', term:'SageMaker Experiments', def:'学習の試行ごとに設定と結果を記録し、比較できるようにする機能。どの条件が良かったかを追跡できる。'},
  ],
  'AIサービス群': [
    {id:'B0105', term:'事前学習済みAIサービス（AI Services）', def:'機械学習の知識が無くてもAPIを呼ぶだけで使える、用途特化のAWSサービス群。RekognitionやTextractなどが該当する。自分でモデルを作る必要がない。'},
    {id:'B0106', term:'Amazon Rekognition', def:'画像・動画を解析し、物体やシーン、顔、不適切コンテンツ、画像内のテキストなどを検出するサービス。'},
    {id:'B0107', term:'Rekognitionの顔比較・顔検索', def:'2つの顔画像が同一人物かを比較したり、登録済みの顔の集合から一致する顔を探したりできる機能。本人確認などに使われる。'},
    {id:'B0108', term:'Amazon Textract', def:'スキャン文書やPDFから、文字だけでなく表やフォームの構造も含めて抽出するサービス。単なるOCRより踏み込んだ情報を取り出せる。'},
    {id:'B0109', term:'TextractとRekognitionの違い', def:'どちらも画像内の文字を読めるが、Textractは文書の「表・フォーム・キーと値」の構造まで理解するのが目的。Rekognitionは画像全般の物体・シーン検出が主目的。'},
    {id:'B0110', term:'Amazon Comprehend', def:'テキストから感情・キーフレーズ・固有表現（人名や地名）・言語などを抽出する自然言語処理サービス。'},
    {id:'B0111', term:'Amazon Comprehend Medical', def:'医療の文章から、症状・薬剤名・検査値などの医療情報を抽出することに特化したサービス。'},
    {id:'B0112', term:'Amazon Transcribe', def:'音声をテキストに変換（文字起こし）するサービス。話者の識別やカスタム語彙の登録にも対応する。'},
    {id:'B0113', term:'Amazon Polly', def:'テキストを自然な音声に変換（音声合成）するサービス。Transcribeとは変換の方向が逆になる。'},
    {id:'B0114', term:'Amazon Translate', def:'テキストを別の言語へ翻訳するサービス。用語集を登録して訳語を統一することもできる。'},
    {id:'B0115', term:'Amazon Kendra', def:'自然言語の質問に対して、社内文書などから適切な答えを探し出すインテリジェント検索サービス。RAGの検索部分として使われることもある。'},
    {id:'B0116', term:'Amazon Lex', def:'音声とテキストの対話型インターフェース（チャットボット・音声ボット）を構築するサービス。意図の認識とスロットの穴埋めを行う。'},
    {id:'B0117', term:'Amazon Personalize', def:'利用履歴などから、個々のユーザーに合わせた推薦を行うサービス。ECサイトの「おすすめ」などに使う。'},
    {id:'B0118', term:'Amazon Fraud Detector', def:'オンライン上の不正行為（なりすまし登録や不正決済など）を検出するモデルを作れるサービス。'},
    {id:'B0119', term:'Amazon Q Business', def:'社内のデータソースに接続し、業務の質問に答えたり要約したりする生成AIアシスタント。'},
    {id:'B0120', term:'Amazon Q Developer', def:'コードの生成・説明・修正やAWSの操作支援を行う、開発者向けの生成AIアシスタント。'},
    {id:'B0121', term:'Amazon Augmented AI（A2I）', def:'AIの推論結果に対して、確信度が低い場合などに人間のレビューを挟む仕組みを組み込めるサービス。Human in the Loopの実装手段。'},
    {id:'B0122', term:'AWS DeepRacer', def:'自律走行するミニカーのシミュレーションを通じて、強化学習を体験しながら学べるサービス。'},
    {id:'B0123', term:'AIサービスと基盤モデルの使い分け', def:'用途が決まっている定型処理（文字起こし・翻訳・物体検出など）は既製のAIサービスが速くて安い。柔軟な文章生成や対話が要るならBedrockの基盤モデルを使う。'},
    {id:'B0124', term:'入力の種類とサービスの対応', def:'画像・動画→Rekognition、文書→Textract、音声→Transcribe、テキスト解析→Comprehend、翻訳→Translate、音声合成→Polly。入力の形から引くと迷いにくい。'},
  ],
  '責任あるAI': [
    {id:'B0125', term:'責任あるAI（Responsible AI）', def:'AIを安全・公平・透明に設計し運用するための考え方。AWSは公平性・説明可能性・プライバシーとセキュリティ・安全性・制御可能性・正確性と堅牢性・ガバナンス・透明性という観点を挙げている。'},
    {id:'B0126', term:'公平性（Fairness）', def:'特定の属性を持つグループに対して、不当に不利な結果を出さないようにすること。SageMaker Clarifyでバイアスを検出できる。'},
    {id:'B0127', term:'説明可能性（Explainability）', def:'モデルがなぜその予測を出したのかを人間が理解できるようにすること。金融や医療など規制の厳しい業種では特に重要になる。'},
    {id:'B0128', term:'透明性（Transparency）', def:'AIシステムの能力・限界・想定用途を明示すること。AWSはAI Service Cardsという文書でこれを提供している。'},
    {id:'B0129', term:'プライバシーとセキュリティ', def:'学習データや推論データに含まれる個人情報を保護し、不正なアクセスから守ること。暗号化とアクセス制御が基本の手段。'},
    {id:'B0130', term:'安全性（Safety）', def:'有害な出力や危険な助言を生成しないようにすること。Bedrock Guardrailsによるフィルタリングが実装手段のひとつ。'},
    {id:'B0131', term:'制御可能性（Controllability）', def:'AIの挙動を人間が監視し、必要に応じて介入・停止できる状態にしておくこと。'},
    {id:'B0132', term:'正確性と堅牢性（Veracity and Robustness）', def:'出力が正確であり、想定外の入力に対しても安定して動作すること。ハルシネーション対策もこの観点に含まれる。'},
    {id:'B0133', term:'ガバナンス（Governance）', def:'AIの利用に関する社内の方針・承認プロセス・記録を整備し、責任の所在を明確にすること。'},
    {id:'B0134', term:'AI Service Cards', def:'AWSの各AIサービスについて、想定される使い方・設計上の選択・性能上の限界などをまとめた透明性のための文書。'},
    {id:'B0135', term:'Human in the Loop（人間の関与）', def:'AIの判断を全自動にせず、重要な判断や確信度の低い結果に人間のレビューを挟む設計。Amazon A2Iで実装できる。'},
    {id:'B0136', term:'データセットの代表性', def:'学習データが、実際に使われる場面の多様性を偏りなく反映していること。特定の属性のデータが不足すると、そのグループで精度が落ちる。'},
    {id:'B0137', term:'モデルの制限事項の開示', def:'どんな条件で精度が落ちるか、どんな用途に使うべきでないかを利用者に伝えること。透明性を担保する実務的な手段。'},
    {id:'B0138', term:'バイアスの種類', def:'学習データの偏り（サンプリングバイアス）、ラベル付けする人の主観による偏り、過去の社会的偏見がデータに残っている場合など、複数の原因がある。'},
  ],
  'セキュリティ・ガバナンス': [
    {id:'B0139', term:'責任共有モデル（AI文脈）', def:'AWSはインフラとサービス自体のセキュリティを担い、利用者はデータの分類・アクセス制御・入出力の扱いに責任を持つ。AIサービスでもこの分担は変わらない。'},
    {id:'B0140', term:'AWS IAM', def:'誰がどのAWSリソースに何をできるかを制御する仕組み。どの利用者がどの基盤モデルを呼び出せるかもIAMで制御する。'},
    {id:'B0141', term:'最小権限の原則', def:'各ユーザーやアプリケーションに、業務に必要な最小限の権限だけを与える考え方。IAMポリシー設計の基本方針。'},
    {id:'B0142', term:'AWS KMS（Key Management Service）', def:'暗号化キーを作成・管理するサービス。保存データの暗号化に使い、キーへのアクセス自体もIAMで制御できる。'},
    {id:'B0143', term:'保存時の暗号化と転送中の暗号化', def:'保存時はS3などに置かれたデータをKMSのキーで暗号化し、転送中はTLSで通信を保護する。AIワークロードでも両方が基本。'},
    {id:'B0144', term:'VPCエンドポイント（AWS PrivateLink）', def:'AWSサービスへの通信をインターネットを経由せずVPC内から行う仕組み。推論データを外に出したくない場合に使う。'},
    {id:'B0145', term:'データ主権（Data Sovereignty）', def:'データが物理的にどの国・地域に保存され、どの法域の規制を受けるかという考え方。リージョン選択がこれに直結する。'},
    {id:'B0146', term:'Amazon Macie', def:'S3に保存されたデータを走査し、個人情報などの機密データを検出して知らせるサービス。学習データの点検に使える。'},
    {id:'B0147', term:'AWS CloudTrail', def:'誰がいつどのAPIを呼んだかを記録する監査ログのサービス。基盤モデルの呼び出し履歴の追跡にも使う。'},
    {id:'B0148', term:'AWS Config', def:'AWSリソースの設定変更を記録し、あるべき設定から外れていないかを継続的に評価するサービス。'},
    {id:'B0149', term:'AWS Audit Manager', def:'各種規制や基準に対する証跡の収集を自動化し、監査への対応を支援するサービス。'},
    {id:'B0150', term:'AWS Artifact', def:'AWSのコンプライアンス報告書や認証文書をダウンロードできるポータル。監査時の説明資料として使う。'},
    {id:'B0151', term:'データの保持と削除の方針', def:'学習データや推論のログをどれだけ保持し、いつ削除するかを定めること。個人情報保護の規制対応で問われる。'},
    {id:'B0152', term:'モデルガバナンス', def:'モデルの用途・学習データ・評価結果・承認履歴を記録し、誰が責任を持つかを明確にする取り組み。SageMaker Model CardsやModel Registryが支援する。'},
  ],
};

