// {id, c:カテゴリID, q:設問, o:[選択肢], a:正解のindex, e:解説}
const QQ = [
{id:'Q001',c:'ai_basic',q:'過去の販売実績から来月の売上金額を予測したい場合、どの学習方式が適していますか？',o:['教師なし学習のクラスタリング','教師あり学習の回帰','強化学習','次元削減'],a:1,e:'連続する数値（売上金額）を予測するのは教師あり学習の「回帰」です。過去の実績という正解付きデータがあるため教師あり学習が使えます。カテゴリを当てる場合は「分類」になります。'},
{id:'Q002',c:'ai_basic',q:'訓練データでは非常に高い精度が出るのに、検証データでは精度が大きく落ちるモデルの状態を何と呼びますか？',o:['過少適合（アンダーフィッティング）','過学習（オーバーフィッティング）','モデルドリフト','ハルシネーション'],a:1,e:'訓練データに適合しすぎて未知のデータに一般化できない状態が過学習です。訓練・検証ともに精度が低い場合は過少適合を疑います。'},
{id:'Q003',c:'ml_flow',q:'病気の検出モデルで「見逃し（実際は陽性なのに陰性と判定）」を減らすことを最優先したい場合、重視すべき評価指標はどれですか？',o:['適合率（Precision）','再現率（Recall）','推論レイテンシ','訓練データ量'],a:1,e:'見逃し（False Negative）を減らしたい場合は再現率（Recall）を重視します。誤検知を減らしたい場合は適合率（Precision）を重視します。'},
{id:'Q004',c:'genai',q:'基盤モデルの出力をより決定的で一貫したものにしたい場合、温度（Temperature）はどう設定しますか？',o:['低くする','高くする','0.5に固定する','温度は出力の多様性に影響しない'],a:0,e:'温度を低くすると確率の高い候補が選ばれやすくなり、出力が決定的で一貫したものになります。高くすると多様で創造的になりますが、ぶれも大きくなります。'},
{id:'Q005',c:'genai',q:'生成AIが、事実に基づかない内容をもっともらしく出力してしまう現象を何と呼びますか？',o:['モデルドリフト','過学習','ハルシネーション','バイアス'],a:2,e:'ハルシネーション（幻覚）です。RAGで根拠となる情報を与える、出力を人間や別の仕組みで検証するといった対策があります。'},
{id:'Q006',c:'prompt',q:'プロンプトに入出力の例を3つ含めてから本題を尋ねる手法を何と呼びますか？',o:['ゼロショットプロンプティング','フューショットプロンプティング','思考の連鎖','継続的事前学習'],a:1,e:'少数の例を示す手法がフューショットプロンプティングです。例を示さないのがゼロショット、途中の推論過程を書かせるのが思考の連鎖です。'},
{id:'Q007',c:'bedrock',q:'社内文書を根拠にした回答を生成AIにさせたい場合、Amazon Bedrockのどの機能が最も適していますか？',o:['Guardrails','Knowledge Bases','Provisioned Throughput','Model Evaluation'],a:1,e:'Knowledge Basesは自社データを検索して回答の根拠に使うRAGをマネージドで実現します。Guardrailsは有害な内容のフィルタリング、Model Evaluationはモデルの比較評価が目的です。'},
{id:'Q008',c:'sagemaker',q:'コードを書けない業務担当者が、GUI操作だけで機械学習の予測モデルを作りたい場合に適したサービスはどれですか？',o:['SageMaker Canvas','SageMaker Ground Truth','SageMaker Model Monitor','SageMaker Clarify'],a:0,e:'SageMaker Canvasはノーコードで機械学習モデルを作成・予測できます。Ground Truthはラベリング、Model Monitorは本番監視、Clarifyはバイアス検出と説明可能性が目的です。'},
{id:'Q009',c:'aiservices',q:'スキャンした請求書のPDFから、表形式の項目と金額を構造を保ったまま抽出したい場合に最適なサービスはどれですか？',o:['Amazon Rekognition','Amazon Comprehend','Amazon Textract','Amazon Polly'],a:2,e:'Textractは文書から文字だけでなく表やフォームの構造も抽出できます。Rekognitionは画像・動画の解析、Comprehendはテキストの自然言語処理、Pollyは音声合成です。'},
{id:'Q010',c:'responsible',q:'学習データに含まれる偏りによって、モデルが特定のグループに不利な予測を出していないかを確認したい場合、どのサービスが役立ちますか？',o:['SageMaker Clarify','SageMaker JumpStart','Amazon Kendra','AWS KMS'],a:0,e:'SageMaker Clarifyはデータとモデルのバイアスを検出し、予測に対する各特徴量の寄与も示します。公平性と説明可能性を確認する手段です。'},
{id:'Q011',c:'secgov',q:'生成AIアプリケーションで、利用者ごとに呼び出せる基盤モデルを制限したい場合、基本となる仕組みはどれですか？',o:['IAMポリシーによるアクセス制御','コンテキストウィンドウの縮小','温度パラメータの調整','トークン数の上限設定'],a:0,e:'どの利用者がどのモデルを呼び出せるかはIAMポリシーで制御します。温度やトークン数は出力の性質やコストに関わる設定で、アクセス制御の手段ではありません。'},

// ── AI・MLの基礎 ──
{id:'Q012',c:'ai_basic',q:'AI・機械学習・ディープラーニングの関係として正しいものはどれですか？',o:['AI ⊂ 機械学習 ⊂ ディープラーニング','ディープラーニング ⊂ 機械学習 ⊂ AI','機械学習 ⊂ AI ⊂ ディープラーニング','3つは互いに独立した別の技術である'],a:1,e:'AIが最も広い概念で、その一分野が機械学習、さらにその一分野がディープラーニングです。'},
{id:'Q013',c:'ai_basic',q:'顧客を購買傾向の似たグループに自動的に分けたい場合、適した学習方式はどれですか？',o:['教師あり学習の分類','教師なし学習のクラスタリング','強化学習','転移学習'],a:1,e:'正解ラベルがない状態でデータの構造からグループを見つけるのはクラスタリングで、教師なし学習に分類されます。'},
{id:'Q014',c:'ai_basic',q:'強化学習の説明として最も適切なものはどれですか？',o:['正解ラベル付きデータから入力と正解の対応を学ぶ','ラベルのないデータから構造を見つける','行動に対する報酬を最大化するよう試行錯誤で学ぶ','既存モデルを別のタスクに転用する'],a:2,e:'強化学習はエージェントが環境で行動し、得られる報酬を最大化するように学習します。ゲームAIやロボット制御に使われます。'},
{id:'Q015',c:'ai_basic',q:'訓練データでも検証データでも精度が低いモデルの状態を何と呼びますか？',o:['過学習','過少適合','モデルドリフト','ハルシネーション'],a:1,e:'過少適合（アンダーフィッティング）です。モデルが単純すぎるなどの理由でデータのパターンを捉えきれていません。過学習は訓練データだけ精度が高い状態です。'},
{id:'Q016',c:'ai_basic',q:'学習済みモデルを別の関連タスクに再利用し、少ないデータと時間で済ませる手法はどれですか？',o:['転移学習','強化学習','クラスタリング','次元削減'],a:0,e:'転移学習です。ゼロから学習するより効率的で、基盤モデルの活用もこの考え方に近いものです。'},
{id:'Q017',c:'ai_basic',q:'学習（トレーニング）と推論（インファレンス）の違いとして正しいものはどれですか？',o:['学習は新しい入力に予測を出すこと、推論はモデルを作ること','学習はモデルを作ること、推論は新しい入力に予測を出すこと','両者は同じ処理である','推論には必ずラベル付きデータが必要である'],a:1,e:'学習はデータからモデルを作る工程、推論は学習済みモデルに新しい入力を与えて予測を得る工程です。実運用で継続的にコストがかかるのは主に推論です。'},

// ── MLライフサイクルと評価 ──
{id:'Q018',c:'ml_flow',q:'スパムメール判定で、正常なメールを誤ってスパムと判定することを減らしたい場合、重視すべき指標はどれですか？',o:['再現率（Recall）','適合率（Precision）','学習時間','モデルのサイズ'],a:1,e:'誤検知（False Positive）を減らしたい場合は適合率を重視します。見逃しを減らしたい場合は再現率です。'},
{id:'Q019',c:'ml_flow',q:'陽性が全体の1%しかないデータで、モデルが常に「陰性」と答えた場合の正解率（Accuracy）はどうなりますか？',o:['約1%と低くなる','約99%と高くなるが、実用的な価値はない','0%になる','計算できない'],a:1,e:'99%が陰性なので正解率は約99%になりますが、陽性を1件も検出できていません。偏ったデータでは正解率だけで判断できないため、適合率や再現率も見る必要があります。'},
{id:'Q020',c:'ml_flow',q:'文章要約タスクの品質評価に使われる指標はどれですか？',o:['ROUGE','適合率','MSE','AUC-ROC'],a:0,e:'ROUGEは参照要約との重なりを見る指標で、要約タスクの評価に使われます。翻訳ではBLEUが使われます。'},
{id:'Q021',c:'ml_flow',q:'テストデータをハイパーパラメータの調整に使ってしまうと、どのような問題が起きますか？',o:['学習が進まなくなる','モデルの性能を過大評価してしまう','推論が遅くなる','データが失われる'],a:1,e:'テストデータは最終評価専用です。調整に使うとそのデータに合わせ込まれ、未知のデータに対する性能を過大評価することになります。'},
{id:'Q022',c:'ml_flow',q:'即時の応答が不要で、大量のデータをまとめて処理したい場合に適した推論方式はどれですか？',o:['リアルタイム推論','バッチ推論','ストリーミング推論','オンライン学習'],a:1,e:'バッチ推論はまとまったデータを定期的に処理する方式で、常時稼働のリアルタイム推論よりコストを抑えられます。'},
{id:'Q023',c:'ml_flow',q:'機械学習の開発から本番運用・監視・再学習までを、自動化された繰り返し可能な仕組みとして回す考え方はどれですか？',o:['MLOps','DevSecOps','AIOps','FinOps'],a:0,e:'MLOpsです。DevOpsの考え方を機械学習に適用したもので、SageMaker Pipelinesなどが実装を支援します。'},

// ── 生成AIの基礎 ──
{id:'Q024',c:'genai',q:'基盤モデル（Foundation Model）の説明として最も適切なものはどれですか？',o:['特定の1つのタスク専用に作られた小規模なモデル','大量かつ多様なデータで事前学習され、多様なタスクに転用できる大規模モデル','ルールベースで動作するプログラム','データベースの一種'],a:1,e:'基盤モデルは幅広いデータで事前学習され、そのままあるいは少しの適応で多様なタスクに使えるモデルです。'},
{id:'Q025',c:'genai',q:'コンテキストウィンドウの説明として正しいものはどれですか？',o:['モデルが1秒間に処理できる文字数','モデルが一度に扱えるトークン数の上限','モデルの学習に使われたデータ量','モデルの応答時間'],a:1,e:'コンテキストウィンドウは一度に扱えるトークン数の上限で、プロンプトと出力の合計がこの範囲に収まる必要があります。'},
{id:'Q026',c:'genai',q:'テキストを意味的な近さが距離として表現される数値ベクトルに変換したものはどれですか？',o:['トークン','埋め込み（Embedding）','プロンプト','パラメータ'],a:1,e:'埋め込み（Embedding）です。意味検索やRAGの検索部分で使われます。'},
{id:'Q027',c:'genai',q:'RAG（検索拡張生成）の主な利点はどれですか？',o:['モデルを再学習せずに最新情報や社内文書を回答の根拠にできる','推論の速度が必ず速くなる','モデルのパラメータ数を減らせる','プロンプトが不要になる'],a:0,e:'RAGは外部データを検索して根拠としてプロンプトに含める手法です。再学習が不要なため、情報が頻繁に更新される用途に向きます。'},
{id:'Q028',c:'genai',q:'次のトークンの候補を、確率の高い上位K個に絞る設定はどれですか？',o:['Temperature','Top-K','Top-P','最大トークン数'],a:1,e:'Top-Kです。Top-Pは候補の個数ではなく累積確率で絞ります。'},
{id:'Q029',c:'genai',q:'現在の大規模言語モデルの土台となっている、アテンション機構を用いたモデル構造はどれですか？',o:['畳み込みニューラルネットワーク','トランスフォーマー','決定木','サポートベクターマシン'],a:1,e:'トランスフォーマーです。文中のどの語に注目すべきかを重み付けするアテンション機構が特徴です。'},
{id:'Q030',c:'genai',q:'テキストだけでなく画像や音声など複数種類の入力を扱えるモデルを何と呼びますか？',o:['マルチモーダルモデル','拡散モデル','埋め込みモデル','蒸留モデル'],a:0,e:'マルチモーダルモデルです。「画像を見せて説明させる」といった使い方ができます。'},
{id:'Q031',c:'genai',q:'ハルシネーションを抑える対策として最も適切なものはどれですか？',o:['温度を最大にする','RAGで根拠となる情報を与える','コンテキストウィンドウを小さくする','出力トークン数を増やす'],a:1,e:'RAGで信頼できる根拠情報を与えることで、事実に基づかない生成を抑えられます。温度を上げると多様性は増しますが、ぶれも大きくなります。'},

// ── プロンプトエンジニアリング ──
{id:'Q032',c:'prompt',q:'複雑な計算問題の正答率を上げるため、途中の推論ステップを順に書かせる手法はどれですか？',o:['ゼロショットプロンプティング','思考の連鎖（Chain-of-Thought）','ネガティブプロンプト','プロンプトテンプレート'],a:1,e:'思考の連鎖です。「順を追って考えてください」といった指示で途中の推論過程を出力させ、複雑な問題の正答率を上げます。'},
{id:'Q033',c:'prompt',q:'モデルの役割や守るべき制約を、会話全体にわたって指定する土台の指示はどれですか？',o:['システムプロンプト','フューショット例','ネガティブプロンプト','出力形式の指定'],a:0,e:'システムプロンプトです。「あなたは丁寧な日本語のカスタマーサポートです」のように、会話全体の前提を定めます。'},
{id:'Q034',c:'prompt',q:'悪意ある入力によってモデルに本来の指示を無視させる攻撃はどれですか？',o:['プロンプトインジェクション','モデルドリフト','過学習','データポイズニング'],a:0,e:'プロンプトインジェクションです。入力の検証やGuardrailsによる多層的な防御が必要になります。'},
{id:'Q035',c:'prompt',q:'システムプロンプトなど、開示するつもりのない指示内容をモデルに吐き出させる攻撃はどれですか？',o:['ジェイルブレイク','プロンプトリーキング','フィッシング','なりすまし'],a:1,e:'プロンプトリーキングです。そもそも機密情報をプロンプトに書かない設計が基本の対策になります。'},
{id:'Q036',c:'prompt',q:'後続のプログラムで処理しやすくするため、生成結果の形を安定させたい場合に有効な工夫はどれですか？',o:['温度を最大にする','JSONなど出力形式を明示的に指定する','プロンプトを短くする','モデルを毎回変える'],a:1,e:'出力形式を明示的に指定すると、ぶれが減り後続処理で扱いやすくなります。あわせて温度を下げると一貫性が高まります。'},
{id:'Q037',c:'prompt',q:'プロンプトエンジニアリングが、ファインチューニングと比べて優れている点はどれですか？',o:['必ず精度が高くなる','モデルを再学習しないため、最も低コストで素早く試せる','大量の学習データが必要になる','専用のGPUが必要になる'],a:1,e:'プロンプトエンジニアリングはモデルを変更しないため、コストと時間の面で最も手軽な改善手段です。'},

// ── Amazon Bedrock ──
{id:'Q038',c:'bedrock',q:'Amazon Bedrockの特徴として正しいものはどれですか？',o:['自分でモデルを一から学習させる必要がある','複数プロバイダーの基盤モデルを単一APIからサーバーレスで利用できる','GPUインスタンスの管理が必要である','利用前に必ずファインチューニングが必要である'],a:1,e:'Bedrockはフルマネージドで、インフラの管理なしに複数の基盤モデルをAPIから利用できます。'},
{id:'Q039',c:'bedrock',q:'生成AIの出力から有害な内容や個人情報を除去したい場合、Amazon Bedrockのどの機能を使いますか？',o:['Knowledge Bases','Agents','Guardrails','Model Evaluation'],a:2,e:'Guardrailsは有害コンテンツ・拒否トピック・禁止語句・個人情報などを入出力の両方でフィルタする安全機構です。'},
{id:'Q040',c:'bedrock',q:'ユーザーの要求を複数のステップに分解し、APIを呼び出してタスクを実行させたい場合に使う機能はどれですか？',o:['Agents','Guardrails','Knowledge Bases','Provisioned Throughput'],a:0,e:'Bedrock Agentsです。単なる文章生成にとどまらず、実際の処理を伴うタスクを実行できます。'},
{id:'Q041',c:'bedrock',q:'安定した大量の推論を行う本番運用で、一定のスループットを確保したい場合に適した課金方式はどれですか？',o:['オンデマンド','Provisioned Throughput','バッチ推論','無料利用枠'],a:1,e:'Provisioned Throughputは一定のスループットを予約する方式で、安定した大量処理が必要な本番運用に向きます。'},
{id:'Q042',c:'bedrock',q:'用途に対してどの基盤モデルが適切かを、自動指標や人手の評価で比較したい場合に使う機能はどれですか？',o:['Model Evaluation','Knowledge Bases','Guardrails','Agents'],a:0,e:'Bedrock Model Evaluationです。複数のモデルを同じ基準で比較して選定できます。'},
{id:'Q043',c:'bedrock',q:'ラベルなしの自社ドメイン文書を大量に使い、基盤モデルの専門知識を底上げする手法はどれですか？',o:['ファインチューニング','継続的事前学習','RAG','プロンプトエンジニアリング'],a:1,e:'継続的事前学習です。ファインチューニングはラベル付き（入出力ペア）のデータで特定タスクへの適合度を高める手法です。'},
{id:'Q044',c:'bedrock',q:'Amazon Bedrockに送ったプロンプトや推論データの取り扱いとして正しいものはどれですか？',o:['基盤モデルの学習に利用される','基盤モデルの学習には利用されない','他の顧客と共有される','モデル提供者に自動的に開示される'],a:1,e:'Bedrockに送ったデータが基盤モデルの学習に使われることはなく、暗号化され他の顧客やモデル提供者と共有されません。'},
{id:'Q045',c:'bedrock',q:'Amazon BedrockとAmazon SageMakerの違いとして最も適切なものはどれですか？',o:['Bedrockは既製の基盤モデルをAPIで使い、SageMakerはモデルの構築・学習・デプロイまでを行う','BedrockはMLの専門知識が必須で、SageMakerは不要である','どちらも同じ機能を提供する','SageMakerは推論だけに使う'],a:0,e:'Bedrockは手軽さ、SageMakerは自由度が特徴です。既製モデルをすぐ使いたいならBedrock、独自にモデルを作り込みたいならSageMakerになります。'},

// ── Amazon SageMaker ──
{id:'Q046',c:'sagemaker',q:'データを渡すだけで前処理・アルゴリズム選択・ハイパーパラメータ調整を自動で行う機能はどれですか？',o:['SageMaker Autopilot','SageMaker Ground Truth','SageMaker Clarify','SageMaker Model Monitor'],a:0,e:'SageMaker Autopilotです。自動機械学習（AutoML）の機能にあたります。'},
{id:'Q047',c:'sagemaker',q:'学習用データにラベルを付ける作業を支援するサービスはどれですか？',o:['SageMaker Canvas','SageMaker Ground Truth','SageMaker Feature Store','SageMaker Pipelines'],a:1,e:'SageMaker Ground Truthです。人手によるラベリングと自動ラベリングを組み合わせられます。'},
{id:'Q048',c:'sagemaker',q:'モデルの用途・学習データ・評価結果・制限事項を記録し、ガバナンスと透明性を確保する機能はどれですか？',o:['SageMaker Model Cards','SageMaker JumpStart','SageMaker Data Wrangler','SageMaker Experiments'],a:0,e:'SageMaker Model Cardsです。モデルに関する情報を文書として残し、説明責任を果たす手段になります。'},
{id:'Q049',c:'sagemaker',q:'呼び出しが断続的な推論において、コストを抑えたい場合に適した方式はどれですか？',o:['常時起動のリアルタイムエンドポイント','Serverless Inference','マネージドスポットトレーニング','Feature Store'],a:1,e:'Serverless Inferenceはリクエストが来たときだけ計算資源を割り当てるため、断続的な呼び出しではコストを抑えられます。'},
{id:'Q050',c:'sagemaker',q:'学習コストを大きく下げたいが、処理が中断される可能性を受け入れられる場合に適した仕組みはどれですか？',o:['マネージドスポットトレーニング','Provisioned Throughput','Serverless Inference','Batch Transform'],a:0,e:'マネージドスポットトレーニングです。余剰の計算資源を使うため安価ですが、中断される可能性があります。'},
{id:'Q051',c:'sagemaker',q:'データ準備から学習・評価・デプロイまでを、繰り返し実行できるワークフローとして定義する機能はどれですか？',o:['SageMaker Pipelines','SageMaker Canvas','SageMaker JumpStart','SageMaker Clarify'],a:0,e:'SageMaker PipelinesはMLOpsの中核となる機能で、一連の工程を自動化して繰り返し実行できます。'},

// ── AIサービス群 ──
{id:'Q052',c:'aiservices',q:'録音された会議の音声を文字に起こしたい場合に使うサービスはどれですか？',o:['Amazon Polly','Amazon Transcribe','Amazon Translate','Amazon Comprehend'],a:1,e:'Transcribeは音声をテキストに変換します。Pollyは逆にテキストを音声に変換します。'},
{id:'Q053',c:'aiservices',q:'商品レビューの文章から、肯定的か否定的かを判定したい場合に使うサービスはどれですか？',o:['Amazon Rekognition','Amazon Comprehend','Amazon Textract','Amazon Kendra'],a:1,e:'Comprehendは感情分析・キーフレーズ抽出・固有表現抽出などの自然言語処理を行います。'},
{id:'Q054',c:'aiservices',q:'社内文書に対して自然言語で質問し、適切な答えを探し出したい場合に使うサービスはどれですか？',o:['Amazon Kendra','Amazon Personalize','Amazon Fraud Detector','Amazon Lex'],a:0,e:'Kendraはインテリジェント検索サービスで、自然言語の質問から社内文書の該当箇所を見つけます。'},
{id:'Q055',c:'aiservices',q:'ECサイトで利用者ごとに商品を推薦したい場合に使うサービスはどれですか？',o:['Amazon Personalize','Amazon Comprehend','Amazon Polly','Amazon Translate'],a:0,e:'Personalizeは利用履歴などから個々のユーザーに合わせた推薦を行うサービスです。'},
{id:'Q056',c:'aiservices',q:'AIの推論結果のうち、確信度が低いものだけ人間のレビューを挟みたい場合に使うサービスはどれですか？',o:['Amazon Augmented AI（A2I）','Amazon Rekognition','Amazon Bedrock Guardrails','SageMaker Clarify'],a:0,e:'Amazon A2Iです。Human in the Loop（人間の関与）を実装する手段になります。'},
{id:'Q057',c:'aiservices',q:'用途が明確な定型処理（文字起こしや翻訳）に対して、既製のAIサービスを使う利点はどれですか？',o:['機械学習の専門知識なしにAPIを呼ぶだけで使える','必ず基盤モデルより高精度になる','学習データを自分で用意する必要がある','推論コストが常に無料になる'],a:0,e:'事前学習済みAIサービスはML知識なしに利用でき、用途が決まっている処理では基盤モデルより手軽で安価に済むことが多いです。'},

// ── 責任あるAI ──
{id:'Q058',c:'responsible',q:'責任あるAIにおける「説明可能性（Explainability）」の説明として適切なものはどれですか？',o:['モデルの推論速度を上げること','モデルがなぜその予測を出したのかを人間が理解できるようにすること','モデルのサイズを小さくすること','モデルを複数用意すること'],a:1,e:'説明可能性は予測の理由を理解できるようにすることです。金融や医療など規制の厳しい業種で特に重要になります。'},
{id:'Q059',c:'responsible',q:'AWSが各AIサービスの想定用途・設計上の選択・性能上の限界をまとめて公開している文書はどれですか？',o:['AI Service Cards','Well-Architected Framework','Service Level Agreement','Trusted Advisor'],a:0,e:'AI Service Cardsです。透明性を確保するための文書として提供されています。'},
{id:'Q060',c:'responsible',q:'学習データに特定の属性のデータが極端に少ない場合、どのような問題が生じやすいですか？',o:['学習が完了しなくなる','そのグループに対する予測精度が低くなり、不公平な結果につながる','推論コストが上がる','モデルサイズが大きくなる'],a:1,e:'データセットの代表性が不足すると、少数グループに対する精度が落ち、公平性の問題につながります。'},
{id:'Q061',c:'responsible',q:'モデルの予測に対して、各特徴量がどれだけ寄与したかを示す機能はどれですか？',o:['SageMaker Clarify','SageMaker JumpStart','Amazon Kendra','Bedrock Agents'],a:0,e:'SageMaker Clarifyはバイアス検出に加え、予測に対する特徴量の寄与を示して説明可能性を支援します。'},
{id:'Q062',c:'responsible',q:'責任あるAIの「制御可能性（Controllability）」が意味することはどれですか？',o:['モデルの学習速度を制御すること','AIの挙動を人間が監視し、必要に応じて介入・停止できること','モデルのパラメータ数を制御すること','推論のコストを制御すること'],a:1,e:'制御可能性は、AIの動作を人間が把握し、必要なときに介入や停止ができる状態を保つことを指します。'},
{id:'Q063',c:'responsible',q:'AIの利用に関する社内の方針・承認プロセス・記録を整備し、責任の所在を明確にすることを何と呼びますか？',o:['ガバナンス','スケーラビリティ','レイテンシ管理','オーケストレーション'],a:0,e:'ガバナンスです。責任あるAIの観点のひとつで、SageMaker Model CardsやModel Registryが実装を支援します。'},
{id:'Q064',c:'responsible',q:'採用選考にAIを使う際、過去の採用実績データをそのまま学習させることの主なリスクはどれですか？',o:['推論が遅くなる','過去の社会的な偏りをモデルが再現してしまう','データ量が不足する','モデルが動作しなくなる'],a:1,e:'過去のデータに偏りが含まれていると、モデルがそれを学習して再現します。バイアスの検出と是正が必要です。'},
{id:'Q065',c:'responsible',q:'生成AIの出力が正確で、想定外の入力に対しても安定して動作することを指す観点はどれですか？',o:['正確性と堅牢性','制御可能性','透明性','プライバシーとセキュリティ'],a:0,e:'正確性と堅牢性（Veracity and Robustness）です。ハルシネーション対策もこの観点に含まれます。'},
{id:'Q066',c:'responsible',q:'重要な判断をAIに全自動で任せず、人間の確認を挟む設計を何と呼びますか？',o:['Human in the Loop','End to End Automation','Zero Trust','Shared Responsibility'],a:0,e:'Human in the Loopです。Amazon A2Iで実装でき、制御可能性と安全性の確保につながります。'},
{id:'Q067',c:'responsible',q:'AIシステムの能力・限界・想定用途を利用者に明示することを指す観点はどれですか？',o:['透明性','公平性','可用性','スケーラビリティ'],a:0,e:'透明性（Transparency）です。AI Service Cardsやモデルの制限事項の開示がその実践にあたります。'},

// ── セキュリティ・ガバナンス ──
{id:'Q068',c:'secgov',q:'AIワークロードにおける責任共有モデルの説明として正しいものはどれですか？',o:['AWSがデータの分類とアクセス制御まで責任を持つ','AWSはインフラとサービス自体、利用者はデータの分類・アクセス制御・入出力の扱いに責任を持つ','利用者はすべての責任を負わない','AIサービスでは責任共有モデルは適用されない'],a:1,e:'AIサービスでも責任共有モデルは適用されます。AWSはクラウド自体のセキュリティを、利用者はクラウド内のデータと設定を担います。'},
{id:'Q069',c:'secgov',q:'推論に使うデータをインターネットを経由させずにAWSサービスへ送りたい場合、適した仕組みはどれですか？',o:['VPCエンドポイント（AWS PrivateLink）','パブリックサブネット','インターネットゲートウェイ','CloudFront'],a:0,e:'VPCエンドポイント（PrivateLink）を使うと、通信をインターネットに出さずVPC内から行えます。'},
{id:'Q070',c:'secgov',q:'学習データに個人情報が含まれていないかをS3上で検出したい場合、適したサービスはどれですか？',o:['Amazon Macie','AWS CloudTrail','AWS Config','AWS Artifact'],a:0,e:'Amazon MacieはS3のデータを走査して機密データを検出します。CloudTrailはAPI呼び出しの監査ログ、Configは設定変更の記録が目的です。'},
{id:'Q071',c:'secgov',q:'基盤モデルの呼び出し履歴を後から追跡したい場合に使うサービスはどれですか？',o:['AWS CloudTrail','Amazon Macie','AWS Artifact','Amazon Kendra'],a:0,e:'CloudTrailは誰がいつどのAPIを呼んだかを記録する監査ログのサービスです。'},
{id:'Q072',c:'secgov',q:'データが物理的にどの国・地域に保存され、どの法域の規制を受けるかという考え方はどれですか？',o:['データ主権','データレイク','データドリフト','データ拡張'],a:0,e:'データ主権（Data Sovereignty）です。AWSではリージョンの選択がこれに直結します。'},
{id:'Q073',c:'secgov',q:'保存データの暗号化に使うキーを作成・管理し、キーへのアクセス自体もIAMで制御できるサービスはどれですか？',o:['AWS KMS','AWS WAF','Amazon GuardDuty','AWS Shield'],a:0,e:'AWS KMS（Key Management Service）です。暗号化キーのライフサイクルを管理します。'},
{id:'Q074',c:'secgov',q:'監査への対応として、AWSのコンプライアンス報告書や認証文書を入手したい場合に使うものはどれですか？',o:['AWS Artifact','AWS Audit Manager','AWS Config','AWS CloudTrail'],a:0,e:'AWS Artifactはコンプライアンス文書をダウンロードできるポータルです。Audit Managerは証跡収集の自動化を支援します。'},
{id:'Q075',c:'secgov',q:'生成AIアプリケーションで最小権限の原則を適用する具体例として適切なものはどれですか？',o:['全利用者に管理者権限を付与する','業務に必要な基盤モデルの呼び出し権限だけをIAMで付与する','IAMを使わずアクセスキーを共有する','すべてのモデルを誰でも呼べるようにする'],a:1,e:'最小権限の原則は、業務に必要な最小限の権限だけを与える考え方です。呼び出せるモデルをIAMで絞るのがその実践にあたります。'},
];

